    static void placementAndAuthority(){var attack=fetch();check(attack.energyCost().equals(Map.of(EnergyType.COLORLESS,1)),"Printed cost removed");var m=fixture(attack);var deck=List.copyOf(m.privateView(B).deck());int rng=m.randomTranscript().size();reveal(m);var p=m.effectCardPrompt(A);check(p.minimum()==1&&p.maximum()==1&&p.candidates().stream().allMatch(c->c.ownerId().equals(B)&&item(m,c)),"Hand chooser, owner or Item classification wrong");check(p.candidates().size()>=2&&m.clientView(B).effectSelection()==null,"Opponent received the attacker's choice");var chosen=p.candidates().getFirst();var own=hand(m,A,"item");var tool=hand(m,B,"tool");for(Runnable r:List.<Runnable>of(()->m.submitEffectCards(B,p.resolutionId(),p.step(),List.of(chosen.instanceId())),()->m.submitEffectCards(A,UUID.randomUUID(),p.step(),List.of(chosen.instanceId())),()->m.submitEffectCards(A,p.resolutionId(),p.step()+1,List.of(chosen.instanceId())),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of()),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(own.instanceId())),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(tool.instanceId())),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(chosen.instanceId(),chosen.instanceId())),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(chosen.instanceId(),p.candidates().getLast().instanceId()))))GeneratedRuleBatch44Test.assertRejectedAtomic(m,r);var expected=new ArrayList<CardInstance>();expected.add(chosen);expected.addAll(deck.subList(0,deck.size()-1));finish(m,chosen);check(m.privateView(B).deck().equals(expected)&&!m.privateView(B).hand().contains(chosen)&&!m.privateView(A).hand().contains(chosen)&&m.privateView(B).hand().contains(deck.getLast()),"Card did not go to exact deck bottom before opponent's ordinary turn draw");check(chosen.ownerId().equals(B)&&m.randomTranscript().size()==rng&&!m.hasPendingEffectChoice()&&m.currentPlayer().equals(B),"Owner changed, shuffle occurred, or action stranded");GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(chosen.instanceId())));}
    static void emptyCases(){for(String mode:List.of("no_items","empty_hand","empty_deck")){var m=fixture(fetch());int rng=m.randomTranscript().size();if(mode.equals("empty_hand"))m.discardHandCardsByEffect(A,B,m.privateView(B).hand().stream().map(CardInstance::instanceId).toList());if(mode.equals("no_items"))m.discardHandCardsByEffect(A,B,m.privateView(B).hand().stream().filter(c->item(m,c)).map(CardInstance::instanceId).toList());if(mode.equals("empty_deck"))m.discardTopDeckCardsByEffect(A,B,m.privateView(B).deck().size());m.attack(A,fetch().id());var r=m.effectCardReveal();if(r!=null)m.acknowledgeEffectReveal(A,r.id());if(mode.equals("empty_deck")){var p=m.effectCardPrompt(A);var selected=p.candidates().getFirst();finish(m,selected);check(m.privateView(B).deck().isEmpty()&&m.privateView(B).hand().contains(selected)&&m.currentPlayer().equals(B),"Single bottom card in empty deck was not the next drawn card");}check(!m.hasPendingEffectChoice()&&m.randomTranscript().size()==rng,"Empty hand/Item/deck case stranded or consumed RNG");}}
    @SuppressWarnings("unchecked") static List<CardInstance> zone(ServerMatch m,String name){try{var f=ServerMatch.class.getDeclaredField("players");f.setAccessible(true);Object state=((Map<?,?>)f.get(m)).get(B);var z=state.getClass().getDeclaredField(name);z.setAccessible(true);return (List<CardInstance>)z.get(state);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    static void capturedWindow(){var m=fixture(fetch());var old=List.copyOf(m.privateView(B).hand());m.attack(A,fetch().id());var r=m.effectCardReveal();var removed=old.stream().filter(c->item(m,c)).findFirst().orElseThrow();var unseen=zone(m,"deck").stream().filter(c->item(m,c)).findFirst().orElseThrow();zone(m,"hand").remove(removed);zone(m,"discard").add(removed);zone(m,"deck").remove(unseen);zone(m,"hand").add(unseen);m.acknowledgeEffectReveal(A,r.id());var p=m.effectCardPrompt(A);check(p.candidates().stream().allMatch(old::contains)&&!p.candidates().contains(removed)&&!p.candidates().contains(unseen),"New or departed cards entered the reveal window");GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(unseen.instanceId())));var stale=p.candidates().getFirst();zone(m,"hand").remove(stale);zone(m,"discard").add(stale);GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(stale.instanceId())));var live=p.candidates().getLast();check(!live.equals(stale),"Not enough Items for stale-card check");finish(m,live);}
    static void sessionActions(){var m=fixture(fetch());var session=MatchSession.multiplayer(m,A,B);session.addSpectator(WATCH);m.attack(A,fetch().id());var view=session.view(A,A);var ack=view.options().stream().filter(o->o.labelZh().contains("确认已查看展示卡牌")).findFirst().orElseThrow();session.submit(A,A,view.revision(),ack.index());var select=session.view(A,A);var visible=new HashSet<String>(MatchRegionModel.from(select).visibleCards().stream().map(c->c.key()).toList());for(var o:select.options())check(visible.containsAll(o.cardKeys()),"Foreign-hand selection anchor was not visible");check(session.view(B,B).options().stream().noneMatch(o->o.labelZh().startsWith("选择卡牌"))&&session.view(WATCH,null).options().isEmpty(),"Wrong seat or spectator could choose opposing Item");var option=select.options().stream().filter(o->o.labelZh().startsWith("选择卡牌")).findFirst().orElseThrow();session.submit(A,A,select.revision(),option.index());var picked=session.view(A,A);var confirm=picked.options().stream().filter(o->o.labelZh().startsWith("确认选牌")).findFirst().orElseThrow();session.submit(A,A,picked.revision(),confirm.index());check(m.currentPlayer().equals(B)&&!m.hasPendingEffectChoice(),"Session could not commit the attacker's opposing-hand choice");}
    static void legacyDiscard(){var j=json();j.getAsJsonArray("triggers").get(0).getAsJsonObject().add("effects",JsonParser.parseString("[{\"type\":\"opponent_choose_discard\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":1}]").getAsJsonArray());var a=BundledCombatData.attack(j,EffectRegistry.standard());var m=fixture(a);m.attack(A,a.id());check(m.effectCardReveal()==null&&m.pendingChoicePlayer().equals(B)&&m.clientView(A).effectSelection()==null,"Legacy self-discard was exposed to or controlled by attacker");var p=m.effectCardPrompt(B);var c=p.candidates().getFirst();m.submitEffectCards(B,p.resolutionId(),p.step(),List.of(c.instanceId()));check(m.privateView(B).discard().contains(c)&&m.currentPlayer().equals(B),"Legacy opponent self-discard changed destination/owner");}
    static void schema(){var attack=json();var data=attack.getAsJsonArray("triggers").get(0).getAsJsonObject().getAsJsonArray("effects").get(1).getAsJsonObject();for(var kv:Map.of("amount","2","trainer_category","TOOL","target","SELF","unexpected","true").entrySet()){var bad=data.deepCopy();bad.addProperty(kv.getKey(),kv.getValue());reject(()->EffectRegistry.standard().parse(bad));}var noReveal=json();noReveal.getAsJsonArray("triggers").get(0).getAsJsonObject().getAsJsonArray("effects").remove(0);reject(()->AttackProgramRules.validate(BundledCombatData.attack(noReveal,EffectRegistry.standard())));var conditional=json();var es=conditional.getAsJsonArray("triggers").get(0).getAsJsonObject().getAsJsonArray("effects");var holder=JsonParser.parseString("{\"type\":\"conditional\",\"conditions\":[{\"type\":\"IS_ACTIVE\",\"target\":\"SELF\"}],\"effects\":[]}").getAsJsonObject();holder.getAsJsonArray("effects").add(es.get(0));es.set(0,holder);reject(()->AttackProgramRules.validate(BundledCombatData.attack(conditional,EffectRegistry.standard())));var e=EffectRegistry.standard().parse(data);for(var t:List.of(EffectTrigger.BEFORE_ATTACK,EffectTrigger.ONCE_PER_TURN,EffectTrigger.ON_CARD_PLAYED)){var p=new EffectProgram(List.of(new TriggeredEffects(t,List.of(),List.of(e))));reject(()->ResumableProgramRules.validate(p,t!=EffectTrigger.ON_CARD_PLAYED,t));}}
